import os

N = int(input())
a = [list(map(int, input().split())) for i in range(N)]


MAXV = N*(N-1)//2
id = [[-1 for _ in range(N)]for _ in range(N)]
to = [[] for _ in range(MAXV)]

def to_id(i, j):
    if i > j:
        j, i = i, j
    return id[i][j]


visited = [False for _ in range(MAXV)]
calculated = [False for _ in range(MAXV)]
dp = [-1 for _ in range(MAXV)]
def dfs(i):
    if visited[i]:
        if not calculated[i]:
            return -1
        else:
            return dp[i]
    visited[i] = True
    dp[i] = 1
    for u in to[i]:
        res = dfs(u)
        if res == -1:
            return -1
        dp[i] = max(dp[i], res+1)
    calculated[i] = True
    return dp[i]

v = 0
for i in range(N):
    for j in range(N):
        if i < j:
            id[i][j] = v
            v += 1

for i in range(N):
    for j in range(N-1):
        a[i][j] = to_id(i, a[i][j]-1)
    for j in range(N-2):
        to[a[i][j+1]].append(a[i][j])

ans = 0
for i in range(v):
    res = dfs(i)
    if res == -1:
        print(-1)
        os.sys.exit()
    ans = max(ans, res)
print(ans)

