def add(A, B):
    for k in A.keys():
        A[k] += B[k]
    return A


def sub(A, B):
    for k in A.keys():
        A[k] -= B[k]
    return A


def count(A):
    return 26 - list(A.values()).count(0)


def identify(i):
    d = sub(sum(i),sum(i-1))
    for k,v in d.items():
        if v == 1:
            return k

# 初期化
