    global BIT, N

    while i < N:
        BIT[i][char] -= 1
        BIT[i][c] += 1
        i += (i & -i)


# 文字数の取り出し
def sum(i):

    global BIT, N

    _sum = {"a": 0, "b": 0, "c": 0, "d": 0, "e": 0,
            "f": 0, "g": 0, "h": 0, "i": 0, "j": 0,
            "k": 0, "l": 0, "m": 0, "n": 0, "o": 0,
            "p": 0, "q": 0, "r": 0, "s": 0, "t": 0,
            "u": 0, "v": 0, "w": 0, "x": 0, "y": 0, "z": 0}
    while i > 0:
        _sum = add(_sum, BIT[i])
        i -= (i & -i)

    return _sum


