def F(n):
	if n == 1:
		return n
	return n * F(n-1)

def G(n, k):
	if k == 1:
		return n
	return n * G(n-1, k-1)

def H(n, k):
	return G(n+k-1, k) // F(k)

ans = 1
for c in Counter(factor).values():
	ans *= H(N, c)
	ans %= MOD

