                if(i == 0 && j==1){
                    f = false;
                }
            }
            if(update) break;
        }
        if(!f) break;
    }
    reverse(ans.begin(), ans.end());
    if(f){
        for(auto e: ans) cout << e << endl;
    }else{
        cout << -1 << endl;
    }
	return 0;
}

import sys
sys.setrecursionlimit(40000)
def func(pos, t, x):

    if pos + t == x:
        return t
    elif pos + t < x:
        new_pos = pos + t
        t += 1
        return func(new_pos, t, x)
    else:
        new_pos = pos - t
        t -= 1
        return func(new_pos, t, x)

def slove(x):
    ans = func(0,0,x)
    return ans
