def funct(mons, curr, possible):
    if not possible:
        return False
    if len(mons) == 0:
        return True
    if 2*curr >= max(mons):
        return True
    smallestMons = min(mons)
    if 2*curr >= smallestMons:
        curr = curr + smallestMons
        mons.remove(smallestMons)
        if funct(mons, curr, True):
            return True
        else:
            return False
    else:
        return False

