  string grid[N];
  int A,B;
  cin >> A >> B;
  for (int i = 0; i < N/2; i++) {
    grid[i] = string(100,'#');
  }
  for (int i = N/2; i < N; i++) {
    grid[i] = string(100,'.');
  }
  place_white(grid,A);
  place_black(grid,B);
  for (int i = 0; i < N; i++) {
    cout << grid[i] << endl;
  }
}

