ATCG = "ATCG"

memo = {}
def dfs(i, last):
    if i == N:
        return 1
    key = (i, last)
    if key in memo:
        return memo[key]
    p = None
    l2 = last[-2:]
    if l2 == "AC":
        p = "G"
    elif l2 == "AG":
        p = "C"
    elif l2 == "GA":
        p = "C"
    elif last == "AGG" or last == "ATG" or last == "AGT":
        p = "C"
    res = 0
    for c in ATCG:
        if c == p:
            continue
        res += dfs(i+1, last[1:] + c)
    memo[key] = res = res % MOD
    return res
